window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-17d7d0b8ca164ba1"]={"versions": [{"id": "FIG-17d7d0b8ca164ba1", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmetamodells (BSW Parameter Definition) für das Modul <code>Mem</code> (Memory Driver) im Kontext der Basic Software (Memory Hardware Abstraction / Drivers). Das Diagramm definiert die Container- und Parameterhierarchie der Moduldefinition.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Wurzelelement ist die Moduldefinition <code>Mem</code> (<code>EcucModuleDef</code>, Kardinalität <code>0..*</code>). Es aggregiert über Kompositionsbeziehungen drei Konfigurationscontainer (<code>+container</code>):</p>\n<ul class=\"fig-list\">\n<li><code>MemGeneral</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..1</code>): Enthält über die Komposition <code>+parameter</code> den booleschen Parameter <code>MemDevErrorDetect</code> (<code>EcucBooleanParamDef</code>, Kardinalität <code>1..1</code>) zur Konfiguration der Entwicklungsschaltkreis-/Fehlererkennung.</li>\n<li><code>MemPublishedInformation</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..1</code>): Enthält über die Komposition <code>+parameter</code> den ganzzahligen Parameter <code>MemErasedValue</code> (<code>EcucIntegerParamDef</code>, Kardinalität <code>1..1</code>, Wertebereich <code>min = 0</code>, <code>max = 4294967295</code>).</li>\n<li><code>MemInstance</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..65535</code>): Repräsentiert die Treiber- oder Speicherinstanzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell zur Strukturierung von XML- bzw. ARXML-Konfigurationsbeschreibungen. Es stellt keine dynamischen Sequenzen oder Laufzeit-Interaktionen dar, legt aber statisch fest, ob Fehlermeldeschnittstellen (DET) über <code>MemDevErrorDetect</code> aktivierbar sind und welche Instanzanzahlen zur Laufzeit generiert werden können.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsstruktur für Memory-Driver-Implementierungen. Das Wurzelelement <code>Mem</code> kann mehrfach vorhanden sein (<code>0..*</code>), erfordert jedoch pro Moduldefinition genau einen <code>MemGeneral</code>- und einen <code>MemPublishedInformation</code>-Container sowie mindestens eine bis maximal 65535 <code>MemInstance</code>-Instanzen. Der gelöschte Zustand (<code>MemErasedValue</code>) ist als 32-Bit-Ganzzahlwert verbindlich zu spezifizieren.</p>"}, {"id": "FIG-19eb672dbc57ecf9", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Konfigurationsmetamodells (BSW Parameter Definition) für das Modul <code>Mem</code> (Memory Driver) im Kontext der Basic Software (Memory Hardware Abstraction / Drivers). Das Diagramm definiert die Container- und Parameterhierarchie der Moduldefinition.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Wurzelelement ist die Moduldefinition <code>Mem</code> (<code>EcucModuleDef</code>, Kardinalität <code>0..*</code>). Es aggregiert über Kompositionsbeziehungen drei Konfigurationscontainer (<code>+container</code>):</p>\n<ul class=\"fig-list\">\n<li><code>MemGeneral</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..1</code>): Enthält über Kompositionen (<code>+parameter</code>) den booleschen Parameter <code>MemDevErrorDetect</code> (<code>EcucBooleanParamDef</code>, Kardinalität <code>1..1</code>) sowie den Integer-Parameter <code>MemIndex</code> (<code>EcucIntegerParamDef</code>, Kardinalität <code>1..1</code>, Wertebereich <code>min = 0</code>, <code>max = 254</code>, <code>symbolicNameValue = true</code>).</li>\n<li><code>MemPublishedInformation</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..1</code>): Enthält über <code>+parameter</code> den Parameter <code>MemErasedValue</code> (<code>EcucIntegerParamDef</code>, Kardinalität <code>1..1</code>, Wertebereich <code>min = 0</code>, <code>max = 4294967295</code>).</li>\n<li><code>MemInstance</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..65535</code>): Zur Abbildung der Speicherinstanzen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell zur Strukturierung von XML- bzw. ARXML-Konfigurationsbeschreibungen. Es stellt keine dynamischen Sequenzen oder Laufzeit-Interaktionen dar, legt aber statisch fest, ob Fehlermeldeschnittstellen (DET) über <code>MemDevErrorDetect</code> aktivierbar sind und welche Instanzanzahlen zur Laufzeit generiert werden können.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Metamodell-Definition für den BSW-Treiber <code>Mem</code>. Für jede Konfiguration von <code>MemGeneral</code> ist verpflichtend ein eindeutiger Treiberindex <code>MemIndex</code> im Intervall 0 bis 254 anzugeben (<code>symbolicNameValue = true</code>), welcher als symbolischer Bezeichner für Treiberaufrufe und Modulidentifikation herangezogen wird. <code>MemDevErrorDetect</code> und <code>MemErasedValue</code> bleiben verbindliche Einzelparameter.</p>"}, {"id": "FIG-3870620a30e1c122", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des ECUC-Metamodells für das BSW-Modul <code>Mem</code> (Memory Driver) einschließlich Multicore-/Partitionierungsunterstützung durch Verknüpfung mit dem externen Modulpaket <code>EcucPartition</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Wurzelelement ist <code>Mem</code> (<code>EcucModuleDef</code>, Kardinalität <code>0..*</code>) mit drei aggregierten Hauptcontainern (<code>+container</code>):</p>\n<ul class=\"fig-list\">\n<li><code>MemGeneral</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..1</code>): Aggregiert Parameter und Referenzen:</li>\n<li><code>MemDevErrorDetect</code> (<code>EcucBooleanParamDef</code>, Kardinalität <code>1..1</code>)</li>\n<li><code>MemMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>, Kardinalität <code>1..1</code>, Wertebereich <code>0..INF</code>, <code>defaultValue = 0.005</code>)</li>\n<li><code>MemIndex</code> (<code>EcucIntegerParamDef</code>, Kardinalität <code>1..1</code>, Wertebereich <code>0..254</code>, <code>symbolicNameValue = true</code>)</li>\n<li><code>MemNamePrefix</code> (<code>EcucStringParamDef</code>, Kardinalität <code>1..1</code>)</li>\n<li><code>MemInvocation</code> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>1..1</code>, <code>defaultValue = DIRECT_STATIC</code>), aggregiert Literale <code>DIRECT_STATIC</code>, <code>INDIRECT_STATIC</code> und <code>INDIRECT_DYNAMIC</code> (<code>EcucEnumerationLiteralDef</code>, jeweils <code>+literal</code>)</li>\n<li><code>MemUseFuncPtrTable</code> (<code>EcucBooleanParamDef</code>, Kardinalität <code>1..1</code>)</li>\n<li><code>MemEcucPartitionRef</code> (<code>EcucReferenceDef</code>, Kardinalität <code>0..<em></code>), referenziert als <code>+destination</code> das externe Element <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>0..</em></code>, aus Paket <code>EcucPartition</code>)</li>\n<li><code>MemPublishedInformation</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..1</code>): Enthält <code>MemErasedValue</code> (<code>EcucIntegerParamDef</code>, Kardinalität <code>1..1</code>, Wertebereich <code>0..4294967295</code>).</li>\n<li><code>MemInstance</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..65535</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell zur Strukturierung von XML- bzw. ARXML-Konfigurationsbeschreibungen. Es stellt keine dynamischen Sequenzen oder Laufzeit-Interaktionen dar, legt aber statisch fest, ob Fehlermeldeschnittstellen (DET) über <code>MemDevErrorDetect</code> aktivierbar sind und welche Instanzanzahlen zur Laufzeit generiert werden können.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsanforderungen für flexible Aufrufmodi und Partitionierung:</p>\n<ul class=\"fig-list\">\n<li><code>MemInvocation</code> steuert die Bindungs- und Aufrufstrategie der Treiberschnittstellen (<code>DIRECT_STATIC</code>, <code>INDIRECT_STATIC</code>, <code>INDIRECT_DYNAMIC</code>) mit Standardwert <code>DIRECT_STATIC</code>.</li>\n<li><code>MemUseFuncPtrTable</code> schaltet die Verwendung einer Funktionszeigertabelle für API-Aufrufe frei.</li>\n<li>Die zyklische Hauptfunktion wird über <code>MemMainFunctionPeriod</code> mit 5 ms Standardperiode parametriert.</li>\n<li><code>MemEcucPartitionRef</code> erlaubt die Zuordnung des Treibers zu null oder mehreren Partitionen (<code>EcucPartition</code>) für partitionsübergreifende Architekturen.</li>\n<li>Über <code>MemNamePrefix</code> wird ein API-Präfix zur Namensraumauflösung festgelegt.</li>\n</ul>"}, {"id": "FIG-7ed4bd6af2f70fb9", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition des ECUC-Metamodells für das BSW-Modul <code>Mem</code> (Memory Driver) einschließlich Multicore-/Partitionierungsunterstützung durch Verknüpfung mit dem externen Modulpaket <code>EcucPartition</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Wurzelelement ist <code>Mem</code> (<code>EcucModuleDef</code>, Kardinalität <code>0..*</code>) mit drei aggregierten Hauptcontainern (<code>+container</code>):</p>\n<ul class=\"fig-list\">\n<li><code>MemGeneral</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..1</code>): Aggregiert Parameter und Referenzen:</li>\n<li><code>MemDevErrorDetect</code> (<code>EcucBooleanParamDef</code>, Kardinalität <code>1..1</code>)</li>\n<li><code>MemMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>, Kardinalität <code>1..1</code>, Wertebereich <code>0..INF</code>, <code>defaultValue = 0.005</code>)</li>\n<li><code>MemIndex</code> (<code>EcucIntegerParamDef</code>, Kardinalität <code>1..1</code>, Wertebereich <code>0..254</code>, <code>symbolicNameValue = true</code>)</li>\n<li><code>MemNamePrefix</code> (<code>EcucStringParamDef</code>, Kardinalität <code>1..1</code>)</li>\n<li><code>MemInvocation</code> (<code>EcucEnumerationParamDef</code>, Kardinalität <code>1..1</code>, <code>defaultValue = DIRECT_STATIC</code>), aggregiert Literale <code>DIRECT_STATIC</code>, <code>INDIRECT_STATIC</code> und <code>INDIRECT_DYNAMIC</code> (<code>EcucEnumerationLiteralDef</code>, jeweils <code>+literal</code>)</li>\n<li><code>MemEcucPartitionRef</code> (<code>EcucReferenceDef</code>, Kardinalität <code>0..<em></code>), referenziert als <code>+destination</code> das externe Element <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>0..</em></code>, aus Paket <code>EcucPartition</code>)</li>\n<li><code>MemPublishedInformation</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..1</code>): Enthält <code>MemErasedValue</code> (<code>EcucIntegerParamDef</code>, Kardinalität <code>1..1</code>, Wertebereich <code>0..4294967295</code>).</li>\n<li><code>MemInstance</code> (<code>EcucParamConfContainerDef</code>, Kardinalität <code>1..65535</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell zur Strukturierung von XML- bzw. ARXML-Konfigurationsbeschreibungen. Es stellt keine dynamischen Sequenzen oder Laufzeit-Interaktionen dar, legt aber statisch fest, ob Fehlermeldeschnittstellen (DET) über <code>MemDevErrorDetect</code> aktivierbar sind und welche Instanzanzahlen zur Laufzeit generiert werden können.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsanforderungen für Memory Driver:</p>\n<ul class=\"fig-list\">\n<li>Die Schnittstellenanbindung erfolgt über den Enumerationsparameter <code>MemInvocation</code> (<code>DIRECT_STATIC</code>, <code>INDIRECT_STATIC</code>, <code>INDIRECT_DYNAMIC</code>) mit Standardbelegung <code>DIRECT_STATIC</code>.</li>\n<li>Zyklische Ausführungen basieren auf der Periodenangabe <code>MemMainFunctionPeriod</code> (Standardwert 0.005 s).</li>\n<li>Die Bindung an Software- und Hardwarepartitionen erfolgt über <code>MemEcucPartitionRef</code> auf Zielcontainer des Typs <code>EcucPartition</code>.</li>\n<li>Modulpräfixe und Symbolnamen werden über <code>MemNamePrefix</code> und <code>MemIndex</code> determiniert.</li>\n</ul>"}], "trans": [{"from": "FIG-17d7d0b8ca164ba1", "to": "FIG-19eb672dbc57ecf9", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Hinzufügung des Parameters <code>MemIndex</code> (<code>EcucIntegerParamDef</code>) im Container <code>MemGeneral</code> mit Kardinalität <code>1..1</code>, Wertebereich <code>min = 0</code>, <code>max = 254</code> und Attribut <code>symbolicNameValue = true</code>.</li>\n</ul>"}, {"from": "FIG-19eb672dbc57ecf9", "to": "FIG-3870620a30e1c122", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Hinzufügung des Parameters <code>MemMainFunctionPeriod</code> (<code>EcucFloatParamDef</code>) zu <code>MemGeneral</code> (Kardinalität <code>1..1</code>, Wertebereich <code>0..INF</code>, Standardwert <code>0.005</code>).</li>\n<li>Hinzufügung des Parameters <code>MemNamePrefix</code> (<code>EcucStringParamDef</code>) zu <code>MemGeneral</code> (Kardinalität <code>1..1</code>).</li>\n<li>Hinzufügung des Aufrufmodus-Parameters <code>MemInvocation</code> (<code>EcucEnumerationParamDef</code>) zu <code>MemGeneral</code> (Kardinalität <code>1..1</code>, Standardwert <code>DIRECT_STATIC</code>) mit den Enumerationsliteralen <code>DIRECT_STATIC</code>, <code>INDIRECT_STATIC</code> und <code>INDIRECT_DYNAMIC</code>.</li>\n<li>Hinzufügung des Konfigurationsparameters <code>MemUseFuncPtrTable</code> (<code>EcucBooleanParamDef</code>) zu <code>MemGeneral</code> (Kardinalität <code>1..1</code>).</li>\n<li>Hinzufügung der Referenz <code>MemEcucPartitionRef</code> (<code>EcucReferenceDef</code>) in <code>MemGeneral</code> (Kardinalität <code>0..<em></code>) mit Ziel <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>, extern referenziert aus Paket <code>EcucPartition</code>, Kardinalität <code>0..</em></code>).</li>\n</ul>"}, {"from": "FIG-3870620a30e1c122", "to": "FIG-7ed4bd6af2f70fb9", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Entfernung des Parameters <code>MemUseFuncPtrTable</code> (<code>EcucBooleanParamDef</code>) aus dem Container <code>MemGeneral</code>.</li>\n</ul>"}]};
